def sub(p,a,b):
    s=open(p).read(); assert a in s,(p,a); open(p,'w').write(s.replace(a,b,1))
p='src/server/services/organization-service.ts'
sub(p,'import { assertCan } from "@/lib/permissions";','import { OwnershipHandoverError } from "@/lib/errors";\nimport { assertCan, PermissionDeniedError } from "@/lib/permissions";')
sub(p,'import { envelope, orgResource, requireFound } from "./_support";','import { notify } from "./notification-service";\nimport { envelope, NotFoundError, orgResource, requireFound } from "./_support";')
sub(p,'import type { OrgId, UserId } from "@/types/common";','import { toIsoTimestamp } from "@/types/common";\nimport type { OrgId, UserId } from "@/types/common";')
sub(p,'import type { Organization, OrganizationSummary } from "@/types/organization";','import type {\n  Organization,\n  OrganizationSummary,\n  OwnershipHandover,\n} from "@/types/organization";')
s=open(p).read()+'''
/** How long an ownership offer stays open. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

async function loadOrg(orgId: OrgId): Promise<Organization> {
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (org.ownerId === actor.userId) return;
  throw new PermissionDeniedError("org:delete", {
    allowed: false,
    action: "org:delete",
    resourceKind: "organization",
    reason: "denied_by_role",
  });
}

/** The pending offer if it is still open (not lapsed), otherwise `null`. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await orgRepo.findPendingHandover(orgId);
  return pending && !isLapsed(pending, now) ? pending : null;
}

/** The offer the actor, as its recipient, may accept or decline. */
async function requireOfferFor(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await orgRepo.findPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, now)) throw new OwnershipHandoverError("expired");
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOrg(orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active" || target.archivedAt) {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const pending = await orgRepo.findPendingHandover(orgId);
  if (pending) {
    if (!isLapsed(pending, now)) {
      throw new OwnershipHandoverError("pending_exists");
    }
    await orgRepo.resolveHandover(
      pending.id,
      "expired",
      toIsoTimestamp(new Date(pending.expiresAt)),
    );
  }

  const handover = await orgRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    toIsoTimestamp(now),
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You have been offered workspace ownership",
    body: `${actor.userId} offered you ownership of ${org.name}`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const handover = await requireOfferFor(actor, orgId, now);

  const org = await loadOrg(orgId);
  const fromUserId = org.ownerId;
  const toUserId = actor.userId;

  const incoming = requireFound(
    await memberRepo.findMember(orgId, toUserId),
    "Member",
    toUserId,
  );
  const outgoing = await memberRepo.findMember(orgId, fromUserId);

  // Promote first so the workspace never goes without an owner.
  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(
      orgId,
      incoming.id,
      "owner",
    );
    await emit("member.role_changed", {
      ...envelope(orgId, toUserId),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  const updated = await orgRepo.setOrgOwner(orgId, toUserId);
  await orgRepo.resolveHandover(handover.id, "accepted", toIsoTimestamp(now));

  if (
    outgoing &&
    outgoing.userId !== toUserId &&
    outgoing.role === "owner" &&
    outgoing.status === "active" &&
    !outgoing.archivedAt
  ) {
    const demoted = await memberRepo.updateMemberRole(
      orgId,
      outgoing.id,
      "admin",
    );
    await emit("member.role_changed", {
      ...envelope(orgId, toUserId),
      memberId: demoted.id,
      from: outgoing.role,
      to: demoted.role,
    });
  }

  await emit("organization.ownership_transferred", {
    ...envelope(orgId, toUserId),
    fromUserId,
    toUserId,
  });

  return updated;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const handover = await requireOfferFor(actor, orgId, now);
  return orgRepo.resolveHandover(handover.id, "declined", toIsoTimestamp(now));
}

export async function cancelOwnershipHandover(
  actor: Actor,
